/* Controlled native script fixture, not a naturally triggered gameplay death. */
#define main old_main
#include "test_party_native.c"
#undef main
static unsigned injecting,phase,complete,bank,death_opcodes;static cpu_t saved;static uint8_t saved_stack[2],saved_operands[3];
static void put(unsigned a,unsigned v){if(a<0x800)n.ram[a]=v;else n.prgram[a-0x6000]=v;}
static void death_observer(nes_t*core,void*state){party_exec(core,state);if(core->cpu.pc==0xc429){unsigned slot=readn(core,0x6314);if(slot<20&&readn(core,0x63a1+slot)==61&&(readn(core,0x638d+slot)&63)==2)death_opcodes++;}if(!injecting||complete||core->cpu.pc!=0xc049)return;if(!phase){saved=n.cpu;bank=(n.mmc1.prg_lo-n.prg)/16384;saved_stack[0]=readn(&n,0x100|saved.s);saved_stack[1]=readn(&n,0x100|((saved.s-1)&255));saved_operands[0]=readn(&n,0x6c3c);saved_operands[1]=readn(&n,0x6c68);saved_operands[2]=readn(&n,0x6c69);}else if(n.cpu.s!=saved.s)return;unsigned pc=0;switch(phase++){case 0:put(0x6c3c,95);put(0x6c68,4);put(0x6c69,0);pc=0xc8c2;break;case 1:n.cpu.a=61;pc=0xc582;break;case 2:n.cpu.a=bank;pc=0xdf85;break;default:put(0x6c3c,saved_operands[0]);put(0x6c68,saved_operands[1]);put(0x6c69,saved_operands[2]);put(0x100|saved.s,saved_stack[0]);put(0x100|((saved.s-1)&255),saved_stack[1]);n.cpu.a=saved.a;n.cpu.x=saved.x;n.cpu.y=saved.y;n.cpu.p=saved.p;n.cpu.s=saved.s;complete=1;return;}put(0x100|n.cpu.s,0xc0);n.cpu.s--;put(0x100|n.cpu.s,0x48);n.cpu.s--;n.cpu.pc=pc;}
int main(int argc,char**argv){if(argc!=3)return 2;char error[512];if(!cart_load(&cart,argv[1],false,error,sizeof error))return 2;for(unsigned i=0;i<8;i++){unsigned v;sscanf(cart.prg_sha256+2*i,"%2x",&v);romid[i]=v;}CHECK(load(&n,argv[2]));party_state_t p;party_init(&p);known_history(&p,1,6);party_update(&p,true,true,true);n.exec_hook=death_observer;n.exec_hook_ud=&p;CHECK(native_verb(7));CHECK(native_verb(22));native_wait(60);CHECK(readn(&n,0x6100)==6);injecting=1;unsigned f;for(f=0;f<300;f++){native_step(0);if(complete&&readn(&n,0x6161)==1&&readn(&n,0x6b43+6)==0&&readn(&n,0x6b5d+6)==1)break;}CHECK(complete&&death_opcodes>0);CHECK(readn(&n,0x6161)==1);CHECK(readn(&n,0x6b43+6)==0);CHECK((readn(&n,0x60b8)&(1u<<6))!=0);CHECK((readn(&n,0x660a+50)&15)==0);CHECK(readn(&n,0x6b5d+6)==1);party_result_t denied=party_check(&n,&p,6,2);CHECK(denied!=PARTY_OK);memcpy(&plain,&n,sizeof plain);CHECK(party_request(&n,&p,6,2)!=PARTY_OK);CHECK(same(&n,&plain));printf("CONTROLLED native script61 fixture (not natural trigger): opcodes%u frames%u costume%u deathcount%u owner50%u room%u denied=%s checks%u failures%u\n",death_opcodes,f,readn(&n,0x6b43+6),readn(&n,0x6161),readn(&n,0x660a+50)&15,readn(&n,0x6b5d+6),party_result_name(denied),checks,failures);party_destroy(&p);cart_free(&cart);return failures?1:0;}
